/**
 * The Niche Hounds hound, alive.
 *
 * The rig is the logo's own hound artwork, cut at its joints (hound-rig.js,
 * generated by tools/hound-rig).
 * Each piece turns about its joint, so standing, sitting, lying down and
 * sleeping are one continuous drawing rather than swapped pictures.
 */
import { RIG, EYE } from './hound-rig.js';

const NS = 'http://www.w3.org/2000/svg';

// Paint order, back to front. Children ride on their parent's transform.
const TREE = [
  ['farHindThigh', [['farHindLower', []]]],
  ['farFrontFore', [['farFrontPaw', []]]],
  ['tail', []],
  ['torso', []],
  ['nearHindThigh', [['nearHindGaskin', [['nearHindLower', [['nearHindPaw', []]]]]]]],
  ['nearFrontFore', [['nearFrontPaw', []]]],
  ['neck', [['head', []]]],
];

const HIP = RIG.nearHindThigh.pivot;

// Joint angles in degrees (clockwise positive), body offset in rig units.
const LYING = {
  r: -3, y: 148,
  nearFrontFore: -77, nearFrontPaw: 72, farFrontFore: -72, farFrontPaw: 70,
  nearHindThigh: -98, nearHindGaskin: 131, nearHindLower: -120, nearHindPaw: 90,
  farHindThigh: -80, farHindLower: -10,
  tail: 20, neck: 8, head: 4,
};

export const POSES = {
  standing: {},
  sitting: {
    r: -30, y: 134, x: 10,
    nearFrontFore: 28, farFrontFore: 58, farFrontPaw: -25,
    nearHindThigh: -48, nearHindGaskin: 105, nearHindLower: -118, nearHindPaw: 90,
    farHindThigh: -40, farHindLower: -20,
    tail: 40, neck: 0, head: 20,
  },
  lying: LYING,
  sleeping: { ...LYING, neck: 22, neckX: 30, neckY: 120, head: 18, eye: 1, tail: 8 },
};

const KEYS = ['x', 'y', 'r', 'tail', 'neck', 'head', 'farHindThigh', 'farHindLower',
  'farFrontFore', 'farFrontPaw', 'nearHindThigh', 'nearHindGaskin', 'nearHindLower', 'nearHindPaw',
  'nearFrontFore', 'nearFrontPaw', 'neckX', 'neckY', 'eye', 'breath'];

export function fullPose(p) {
  const out = {};
  for (const k of KEYS) out[k] = (p && p[k]) || 0;
  return out;
}

export function buildHound(svg) {
  const nodes = {};
  const make = (tag, attrs, parent) => {
    const el = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
    parent.appendChild(el);
    return el;
  };
  const root = make('g', { class: 'hound-root' }, svg);
  const addPiece = ([name, kids], parent) => {
    const g = make('g', { 'data-piece': name }, parent);
    make('path', { class: 'hound-back', d: RIG[name].back }, g);
    make('path', { class: 'hound-art', d: RIG[name].art, 'fill-rule': 'evenodd' }, g);
    nodes[name] = g;
    if (name === 'head') {
      // Eyelid: a patch of coat over the eye with the closed lid line on it.
      const lid = make('g', { class: 'hound-lid' }, g);
      make('ellipse', { cx: EYE.cx, cy: EYE.cy, rx: EYE.rx + 1.5, ry: EYE.ry + 1.5, class: 'hound-lid-coat' }, lid);
      make('path', {
        class: 'hound-lid-line',
        d: `M${EYE.cx - EYE.rx} ${EYE.cy - 1}Q${EYE.cx} ${EYE.cy + EYE.ry + 1} ${EYE.cx + EYE.rx} ${EYE.cy - 2.5}`,
      }, lid);
      nodes.lid = lid;
    }
    for (const kid of kids) addPiece(kid, g);
  };
  for (const branch of TREE) addPiece(branch, root);
  nodes.root = root;
  return nodes;
}

const f = (n) => Math.round(n * 100) / 100;

export function applyPose(nodes, pose) {
  const p = fullPose(pose);
  nodes.root.setAttribute('transform',
    `translate(${f(p.x)} ${f(p.y)}) rotate(${f(p.r)} ${HIP[0]} ${HIP[1]})`);
  for (const name of Object.keys(RIG)) {
    if (name === 'torso') continue;
    const [px, py] = RIG[name].pivot;
    const shift = name === 'neck' ? `translate(${f(p.neckX)} ${f(p.neckY)}) ` : '';
    nodes[name].setAttribute('transform', `${shift}rotate(${f(p[name] || 0)} ${px} ${py})`);
  }
  // Breathing lifts the back a touch; the belly line stays put.
  const s = 1 + p.breath;
  nodes.torso.setAttribute('transform', `translate(0 ${f(460 * (1 - s))}) scale(1 ${f(s * 10000) / 10000})`);
  const k = Math.min(1, Math.max(0, p.eye));
  nodes.lid.setAttribute('opacity', k > 0.02 ? 1 : 0);
  nodes.lid.setAttribute('transform',
    `translate(0 ${f((EYE.cy - EYE.ry) * (1 - k))}) scale(1 ${f(Math.max(k, 0.001))})`);
}

// Which joints move when, as a fraction of each transition. Settling down
// folds the hind legs first; getting up plants the front legs first.
const GROUPS = {
  body: ['x', 'y', 'r'],
  front: ['nearFrontFore', 'nearFrontPaw', 'farFrontFore', 'farFrontPaw'],
  hind: ['nearHindThigh', 'nearHindGaskin', 'nearHindLower', 'nearHindPaw', 'farHindThigh', 'farHindLower'],
  head: ['neck', 'neckX', 'neckY', 'head'],
  tail: ['tail'],
  eye: ['eye'],
};
const TIMING = {
  sitting: { ms: 1900, hind: [0, 0.7], body: [0.12, 1], front: [0.1, 1], head: [0.2, 1] },
  lying: { ms: 2300, front: [0, 0.75], body: [0.15, 1], hind: [0.05, 1], head: [0.3, 1] },
  sleeping: { ms: 3000, head: [0, 1], eye: [0.45, 0.95], tail: [0.3, 1] },
  standing: { ms: 1300, eye: [0, 0.12], head: [0, 0.5], body: [0, 0.6], front: [0.1, 0.85], hind: [0.2, 1], tail: [0.2, 1] },
};
const WINDOW = {};
for (const [pose, t] of Object.entries(TIMING)) {
  WINDOW[pose] = {};
  for (const [g, keys] of Object.entries(GROUPS)) for (const k of keys) WINDOW[pose][k] = t[g] || [0, 1];
}

const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const clamp01 = (t) => Math.min(1, Math.max(0, t));

export function blend(from, to, target, t) {
  const A = fullPose(from), B = fullPose(to), out = {};
  for (const k of KEYS) {
    const [s, e] = WINDOW[target][k] || [0, 1];
    out[k] = A[k] + (B[k] - A[k]) * ease(clamp01((t - s) / (e - s)));
  }
  return out;
}

// Seconds of stillness before each step down.
const IDLE_STEPS = [['sitting', 9], ['lying', 22], ['sleeping', 40]];
const ORDER = ['standing', 'sitting', 'lying', 'sleeping'];

const LIFE = {
  standing: { breath: [0.007, 3.2], wag: [6, 1.5], head: 1.6 },
  sitting: { breath: [0.008, 3.6], wag: [3.5, 0.9], head: 1.2 },
  lying: { breath: [0.009, 4.2], wag: [2.5, 0.5], head: 0.8 },
  sleeping: { breath: [0.016, 5.4], wag: [1.2, 0.18], head: 0 },
};

/**
 * Build the hound in `svg` and run it.
 * opts.reducedMotion: MediaQueryList for prefers-reduced-motion.
 * opts.hold: pose name to hold (preview), opts.idleScale: speeds up idle timers.
 */
export function runHound(svg, opts = {}) {
  const nodes = buildHound(svg);
  const rm = opts.reducedMotion;
  const still = () => !!(rm && rm.matches);
  const idleScale = opts.idleScale || 1;
  const now = () => performance.now();

  let state = opts.hold && POSES[opts.hold] ? opts.hold : 'standing';
  let current = fullPose(POSES[state]);
  let tween = null; // {from, to, target, start, ms}
  let lastActive = now();
  let blinkAt = now() + 2500;
  let raf = 0;
  let visible = true;

  const go = (target) => {
    if (target === state && !tween) return;
    state = target;
    svg.dataset.pose = target;
    if (still()) {
      tween = null;
      current = fullPose(POSES[target]);
      applyPose(nodes, current);
      return;
    }
    tween = { from: current, to: POSES[target], target, start: now(), ms: TIMING[target].ms };
    wake();
  };

  const wakeUp = () => {
    lastActive = now();
    if (opts.hold) return;
    if (state !== 'standing') go('standing');
  };

  const tick = () => {
    raf = 0;
    const t = now();
    if (!opts.hold) {
      const idle = (t - lastActive) / 1000 * idleScale;
      let want = 'standing';
      for (const [pose, secs] of IDLE_STEPS) if (idle >= secs) want = pose;
      // Only ever step down one stage at a time.
      if (ORDER.indexOf(want) > ORDER.indexOf(state) && !tween) go(ORDER[ORDER.indexOf(state) + 1]);
    }
    let pose;
    if (tween) {
      const k = clamp01((t - tween.start) / tween.ms);
      pose = blend(tween.from, tween.to, tween.target, k);
      if (k >= 1) tween = null;
    } else {
      pose = fullPose(POSES[state]);
    }
    current = pose;
    const shown = { ...pose };
    if (!still()) {
      const life = LIFE[state];
      const sec = t / 1000;
      const b = life.breath[0] * (0.5 - 0.5 * Math.cos((sec / life.breath[1]) * Math.PI * 2));
      shown.breath = b;
      shown.neckY += -173 * b;
      shown.tail += life.wag[0] * Math.sin(sec * life.wag[1] * Math.PI * 2);
      shown.head += life.head * Math.sin(sec * 0.23 * Math.PI * 2) + life.head * 0.6 * Math.sin(sec * 0.61);
      if (state !== 'sleeping' && !tween) {
        if (t > blinkAt + 160) blinkAt = t + 2200 + Math.random() * 4200;
        else if (t > blinkAt) shown.eye = Math.max(shown.eye, Math.sin(((t - blinkAt) / 160) * Math.PI));
      }
    }
    applyPose(nodes, shown);
    if (visible && !still()) raf = requestAnimationFrame(tick);
    else if (visible && !opts.hold) setTimeout(() => { if (!raf) raf = requestAnimationFrame(tick); }, 1000);
  };

  function wake() {
    if (!raf && visible) raf = requestAnimationFrame(tick);
  }

  const events = ['pointermove', 'pointerdown', 'keydown', 'wheel', 'scroll', 'touchstart'];
  const onActive = () => { wakeUp(); wake(); };
  for (const e of events) window.addEventListener(e, onActive, { passive: true });
  const io = new IntersectionObserver((entries) => {
    visible = entries.some((en) => en.isIntersecting) && !document.hidden;
    if (visible) wake();
  });
  io.observe(svg);
  const onVis = () => { visible = !document.hidden; if (visible) { lastActive = now(); wake(); } };
  document.addEventListener('visibilitychange', onVis);
  if (rm && rm.addEventListener) rm.addEventListener('change', wake);

  svg.dataset.pose = state;
  applyPose(nodes, current);
  wake();

  return {
    get pose() { return state; },
    destroy() {
      for (const e of events) window.removeEventListener(e, onActive);
      document.removeEventListener('visibilitychange', onVis);
      io.disconnect();
      if (raf) cancelAnimationFrame(raf);
    },
  };
}
